#!/bin/bash
# Full pipeline for one CIC-IDS2017 day: pcapng to pcap -> align -> Suricata 8.0.7 -> match alerts to labels -> store originals on the NAS.
# Usage: run_cicids2017.sh <day, e.g. wednesday>
# Requires: ~/datasets/cicids2017/pcaps/<official file name> fully downloaded from the mirror (hf_download.sh checked the mirror's sha256);
#       ~/datasets/cicids2017/conn/<day>.conn.log.labeled generated by cic_to_conn.py.
set -euo pipefail
day=$1
HERE=$(cd "$(dirname "$0")" && pwd)
C=/home/sixsquare/datasets/cicids2017
R=/home/sixsquare/datasets/detection
NAS=/mnt/nas/dataset/cicids2017
declare -A FILE=([monday]=Monday-WorkingHours [tuesday]=Tuesday-WorkingHours [wednesday]=Wednesday-workingHours
                 [thursday]=Thursday-WorkingHours [friday]=Friday-WorkingHours)
f=${FILE[$day]}
src=$C/pcaps/$f.pcap
# Only one pipeline per day at a time (several run_cicids2017_all.sh may be running); later ones wait for the earlier one, and finished steps are skipped via marker files
exec 9>"$C/.lock.$day"; flock 9
want=$(cut -d' ' -f1 "$C/official_md5/$f.md5")
if [ -f "$src" ]; then
    [ -f "$src.ok" ] || { echo "$f 還沒下載完"; exit 1; }
    [ "$(md5sum < "$src" | cut -d' ' -f1)" = "$want" ] || { echo "$f 和官方 md5 不符"; exit 1; }
    echo "official md5 ok: $f"
fi

# 1. The alignment tool only reads libpcap and the official files are pcapng -> convert to pcap (keeping the original time precision)
mkdir -p "$C/pcap"
out=$C/pcap/$day.pcap
if [ ! -f "$out.ok" ]; then
    editcap -F pcap "$src" "$out"
    touch "$out.ok"
fi

# 2. Align (same definition as IoT-23)
mkdir -p "$C/align"
[ -f "$C/align/$day.json" ] || python3 -I "$HERE/../iot23/align_stream.py" "$C/conn/$day.conn.log.labeled" "$out" --json "$C/align/$day.json"

# 3. Suricata 8.0.7 (full), keeping only alerts in eve.
#    HOME_NET is the victim subnet 192.168.10.0/24: the attacker appears as 172.16.0.1 after the firewall's NAT,
#    and Suricata's default HOME_NET includes 172.16.0.0/12, which treats the attacker as an internal host so external-to-internal rules never fire.
o=$R/cicids2017/$day
if [ ! -f "$o/done.txt" ]; then
    rm -rf "$o"; mkdir -p "$o"
    docker run --rm --user 1000:1000 -v "$C/pcap":/pcap:ro -v "$R/rules":/rules:ro -v "$o":/out \
        wnc-suricata8 suricata -v -c /rules/detect.yaml -S /rules/et_all.rules --runmode single \
        --set mpm-algo=ac-ks --set spm-algo=bm --set unix-command.enabled=no -k none \
        --set 'vars.address-groups.HOME_NET=[192.168.10.0/24]' \
        -r "/pcap/$day.pcap" -l /out > "$o/run.log" 2>&1
    echo "rc=$?" > "$o/done.txt"
fi

# 4. Match alerts to labels
mkdir -p "$R/match_cicids2017"
python3 -I "$HERE/match_iot23.py" "$C/conn/$day.conn.log.labeled" "$o/eve.json" \
    "$R/rules/gw_corp_sids.txt" "$R/rules/iplist_sids.txt" "$R/match_cicids2017/$day.json"

# 5. Store the original (pcapng) on the NAS and delete the local copy only after the md5 matches (last step: the NAS is on WiFi and slow, so it doesn't block analysis)
mkdir -p "$NAS/pcaps"
if [ -f "$src" ] && [ ! -f "$NAS/pcaps/$f.pcap.md5ok" ]; then
    [ "$(stat -c %s "$NAS/pcaps/$f.pcap" 2>/dev/null)" = "$(stat -c %s "$src")" ] || cp "$src" "$NAS/pcaps/$f.pcap"
    [ "$(md5sum < "$NAS/pcaps/$f.pcap" | cut -d' ' -f1)" = "$want" ] || { echo "NAS 複本 md5 不符"; exit 1; }
    touch "$NAS/pcaps/$f.pcap.md5ok"
fi
rm -f "$src" "$src.ok"

echo "$day done"
